/* @lc app=leetcode id=3242 lang=kotlin */ class NeighborSum(val grid: Array<IntArray>, val pos: HashMap<Int, Pair<Int, Int>> = HashMap<Int, Pair<Int, Int>>().also { m -> grid.indices.forEach { i -> grid.indices.forEach { j -> m[grid[i][j]] = i to j } } }) { fun adjacentSum(value: Int): Int = pos[value]!!.let { (i, j) -> listOf(i + 1 to j, i - 1 to j, i to j + 1, i to j - 1).filter { (a, b) -> a in grid.indices && b in grid.indices }.sumOf { (a, b) -> grid[a][b] } } fun diagonalSum(value: Int): Int = pos[value]!!.let { (i, j) -> listOf(i + 1 to j + 1, i - 1 to j - 1, i + 1 to j - 1, i - 1 to j + 1).filter { (a, b) -> a in grid.indices && b in grid.indices }.sumOf { (a, b) -> grid[a][b] } } }